"""Native vector illustrations of two otherwise easily conflated spaces."""
def coefficients():
 def xy(x,y):return f'{215+90*x:.2f},{190-90*y:.2f}'
 return '''<figure class="pr-model"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 760 330" role="img" aria-label="Coefficient line c1 plus two c2 equals four fifths; minimum norm at four twenty-fifths and eight twenty-fifths"><rect x="12" y="12" width="442" height="300" rx="8" fill="#f4f8f6" stroke="#ccdcd7"/><text x="28" y="42" class="pr-prose">Coefficient space, not physical vector space</text><path d="M60 190H420 M215 280V75" stroke="#a6bcb5" fill="none"/><polyline points="'''+xy(1.6,-.4)+' '+xy(-.8,.8)+'''" stroke="#17636a" stroke-width="2.5" fill="none"/><polyline points="'''+xy(0,0)+' '+xy(4/25,8/25)+'''" stroke="#b34a3c" stroke-width="2.5" fill="none"/><circle cx="229.4" cy="161.2" r="4" fill="#b34a3c"/><circle cx="215" cy="190" r="3" fill="#536b9c"/><text x="480" y="55" class="pr-prose">Every point on the line satisfies</text><text x="480" y="80" class="pr-math">c₁ + 2c₂ = 4/5.</text><text x="480" y="132" class="pr-prose">The shortest coefficient vector is</text><text x="480" y="157" class="pr-math">(4/25, 8/25).</text><text x="480" y="210" class="pr-prose">All these coefficient choices give</text><text x="480" y="235" class="pr-math">the same physical p = (4/5, 8/5, 0).</text></svg><figcaption>Problem2: nonunique coefficients form an affine line in two-dimensional coefficient space. The shortest vector from its origin selects the minimum-norm coefficients. The three-dimensional physical projection remains unique for every point on this line.</figcaption></figure>'''
def polynomial():
 pts=[(-1+i/50)for i in range(101)]
 curve=' '.join(f'{225+150*t:.2f},{260-180*t*t:.2f}'for t in pts)
 area=curve+' 375,200 75,200'
 return '''<figure class="pr-model"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 760 330" role="img" aria-label="Quadratic function and its constant integral projection, with signed residual gaps"><rect x="12" y="12" width="442" height="300" rx="8" fill="#f4f8f6" stroke="#ccdcd7"/><text x="28" y="42" class="pr-prose">Function plot on the interval [−1, 1]</text><polygon points="'''+area+'''" fill="#e3e6ed"/><path d="M60 260H415 M225 280V65" stroke="#a6bcb5" fill="none"/><polyline points="'''+curve+'''" stroke="#536b9c" stroke-width="2.5" fill="none"/><path d="M75 200H375" stroke="#17636a" stroke-width="2.5"/><text x="480" y="65" class="pr-prose">Blue curve: the input function</text><text x="480" y="90" class="pr-math">f(t) = t².</text><text x="480" y="142" class="pr-prose">Green line: the closest polynomial</text><text x="480" y="167" class="pr-math">p(t) = 1/3.</text><text x="480" y="219" class="pr-prose">The squared vertical gaps integrate</text><text x="480" y="244" class="pr-math">to 8/45.</text></svg><figcaption>Problem34: the shaded gaps represent the function residual, whose integral products with both 1 and t vanish. The picture is a graph of function values, not a coordinate-vector angle diagram; its unweighted shaded area is not the squared-error integral.</figcaption></figure>'''
